input.oldString:
function draw() {
    ctx.clearRect(0, 0, width, height);
    // Draw ship
    ctx.save();
    ctx.translate(ship.x, ship.y);
    ctx.rotate(ship.angle);
    ctx.beginPath();
    ctx.moveTo(20, 0);
    ctx.lineTo(-10, -10);
    ctx.lineTo(-10, 10);
    ctx.closePath();
    ctx.fillStyle = '#0ff';
    ctx.fill();
    ctx.restore();

    // Draw asteroids
    ctx.fillStyle = '#888';
    asteroids.forEach(a => {
      if (a.mined) return; // skip mined
      ctx.beginPath();
      ctx.arc(a.x, a.y, a.radius, 0, Math.PI * 2);
      ctx.fill();
    });

    // Draw lasers
    ctx.strokeStyle = '#f00';
    ctx.lineWidth = 2;
    lasers.forEach(l => {
      ctx.beginPath();
      ctx.moveTo(l.x, l.y);
      ctx.lineTo(l.x - Math.cos(l.angle) * 5, l.y - Math.sin(l.angle) * 5);
      ctx.stroke();
    });

    // UI: fuel and hull
    ctx.fillStyle = '#fff';
    ctx.font = '14px sans-serif';
    ctx.fillText(`Fuel: ${ship.fuel.toFixed(0)}`, 10, 20);
    ctx.fillText(`Hull: ${ship.hull.toFixed(0)}`, 10, 40);
    if (ship.fuel <= 0 || ship.hull <= 0) {
      ctx.fillStyle = 'rgba(0,0,0,0.7)';
      ctx.fillRect(0, 0, width, height);
      ctx.fillStyle = '#fff';
      ctx.textAlign = 'center';
      ctx.font = '30px sans-serif';
      ctx.fillText('Game Over', width / 2, height / 2);
    }
  }

input.newString:
function draw() {
    // Background: black with starfield
    ctx.fillStyle = '#000';
    ctx.fillRect(0, 0, width, height);
    ctx.fillStyle = '#fff';
    stars.forEach(s => {
      ctx.beginPath();
      ctx.arc(s.x, s.y, s.radius, 0, Math.PI * 2);
      ctx.fill();
    });

    // Draw asteroids with shading gradient
    asteroids.forEach(a => {
      if (a.mined) return; // skip mined
      const grad = ctx.createRadialGradient(a.x, a.y, a.radius * 0.2, a.x, a.y, a.radius);
      grad.addColorStop(0, '#bbb');
      grad.addColorStop(1, '#555');
      ctx.fillStyle = grad;
      ctx.beginPath();
      ctx.arc(a.x, a.y, a.radius, 0, Math.PI * 2);
      ctx.fill();
    });

    // Draw ship with thrust flame
    ctx.save();
    ctx.translate(ship.x, ship.y);
    ctx.rotate(ship.angle);
    // Ship body
    ctx.beginPath();
    ctx.moveTo(20, 0);
    ctx.lineTo(-10, -10);
    ctx.lineTo(-10, 10);
    ctx.closePath();
    ctx.fillStyle = '#0ff';
    ctx.fill();
    // Thrust flame when accelerating
    if (keys['ArrowUp'] && ship.fuel > 0) {
      ctx.beginPath();
      ctx.moveTo(-10, -6);
      ctx.lineTo(-18, 0);
      ctx.lineTo(-10, 6);
      ctx.closePath();
      const flameGrad = ctx.createRadialGradient(0, 0, 2, 0, 0, 12);
      flameGrad.addColorStop(0, 'orange');
      flameGrad.addColorStop(1, 'red');
      ctx.fillStyle = flameGrad;
      ctx.fill();
    }
    ctx.restore();

    // Draw lasers with glow
    ctx.strokeStyle = '#f44';
    ctx.lineWidth = 2;
    lasers.forEach(l => {
      ctx.beginPath();
      ctx.moveTo(l.x, l.y);
      ctx.lineTo(l.x - Math.cos(l.angle) * 5, l.y - Math.sin(l.angle) * 5);
      ctx.stroke();
    });

    // UI: fuel and hull
    ctx.fillStyle = '#fff';
    ctx.font = '14px sans-serif';
    ctx.fillText(`Fuel: ${ship.fuel.toFixed(0)}`, 10, 20);
    ctx.fillText(`Hull: ${ship.hull.toFixed(0)}`, 10, 40);
    if (ship.fuel <= 0 || ship.hull <= 0) {
      ctx.fillStyle = 'rgba(0,0,0,0.7)';
      ctx.fillRect(0, 0, width, height);
      ctx.fillStyle = '#fff';
      ctx.textAlign = 'center';
      ctx.font = '30px sans-serif';
      ctx.fillText('Game Over', width / 2, height / 2);
    }
  }

